// scanNoteWatchers scans rows into NoteWatcher entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanNoteWatchers(rows database.Rows, columns []string) ([]*NoteWatcher, error) {
	var result []*NoteWatcher
	for rows.Next() {
		n := &NoteWatcher{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "user_id":
				targets[idx] = &n.UserID
			case "note_id":
				targets[idx] = &n.NoteID
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan note_watcher: %w", err)
		}

		result = append(result, n)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate note_watcher rows: %w", err)
	}
	return result, nil
}

