// Paginate returns a page of note_watchers with total count for offset-based pagination.
// A nil filter paginates all note_watchers.
func (c *noteWatcherClient) Paginate(ctx context.Context, input PaginateInput[NoteWatcherFilter], opts ...func(*CallOptions[NoteWatcherFieldOptions])) (*PaginateResult[NoteWatcher], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("paginate note_watchers: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableNoteWatchers, Schema: "audit",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[NoteWatcherFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		noteWatchers, err := c.GetMany(ctx, &GetNoteWatchersInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		return &PaginateResult[NoteWatcher]{
			Items:      noteWatchers,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    input.Limit > 0 && int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("paginate note_watchers: %w", err)
	}
	if result == nil {
		return nil, nil
	}
	return result.(*PaginateResult[NoteWatcher]), nil
}

// Connection returns a Relay-style cursor-paginated connection of note_watchers.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *noteWatcherClient) Connection(ctx context.Context, input ConnectionInput[NoteWatcherFilter], opts ...func(*CallOptions[NoteWatcherFieldOptions])) (*Connection[NoteWatcher], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection note_watchers: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableNoteWatchers, Schema: "audit",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[NoteWatcherFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeNoteWatcherCursor(*input.After, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeNoteWatcherCursor(*input.Before, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		noteWatchers, err := c.GetMany(ctx, &GetNoteWatchersInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		// Trim extra row and determine page boundaries
		hasMore := len(noteWatchers) > limit
		if hasMore {
			noteWatchers = noteWatchers[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(noteWatchers)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[NoteWatcher], len(noteWatchers))
		for i, row := range noteWatchers {
			cursor, err := encodeNoteWatcherCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[NoteWatcher]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[NoteWatcher]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("connection note_watchers: %w", err)
	}
	if result == nil {
		return nil, nil
	}
	return result.(*Connection[NoteWatcher]), nil
}

// encodeNoteWatcherCursor encodes cursor key values as a base64 JSON string.
func encodeNoteWatcherCursor(keys []string, n *NoteWatcher) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "user_id":
			out["user_id"] = n.UserID
		case "note_id":
			out["note_id"] = n.NoteID
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode note_watcher cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// decodeNoteWatcherCursor decodes a cursor string into its key values,
// each unmarshaled into the key column's Go type.
func decodeNoteWatcherCursor(encoded string, keys []string) (map[string]any, error) {
	raw, err := decodeCursor(encoded, keys)
	if err != nil {
		return nil, err
	}
	var row NoteWatcher
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "user_id":
			err = json.Unmarshal(raw[key], &row.UserID)
			out[key] = row.UserID
		case "note_id":
			err = json.Unmarshal(raw[key], &row.NoteID)
			out[key] = row.NoteID
		}
		if err != nil {
			return nil, err
		}
		if cursorValueIsNull(out[key]) {
			return nil, ErrInvalidCursor
		}
	}
	return out, nil
}

