// Connection returns a Relay-style cursor-paginated connection of user_categories.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *userCategoryClient) Connection(ctx context.Context, input ConnectionInput[UserCategoryFilter], opts ...func(*CallOptions[UserCategoryFieldOptions])) (*Connection[UserCategory], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection user_categories: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableUserCategories, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[UserCategoryFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeUserCategoryCursor(*input.After, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeUserCategoryCursor(*input.Before, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		userCategories, err := c.GetMany(ctx, &GetUserCategoriesInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		// Trim extra row and determine page boundaries
		hasMore := len(userCategories) > limit
		if hasMore {
			userCategories = userCategories[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(userCategories)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[UserCategory], len(userCategories))
		for i, row := range userCategories {
			cursor, err := encodeUserCategoryCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[UserCategory]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[UserCategory]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("connection user_categories: %w", err)
	}
	if result == nil {
		return nil, nil
	}
	return result.(*Connection[UserCategory]), nil
}

// encodeUserCategoryCursor encodes cursor key values as a base64 JSON string.
func encodeUserCategoryCursor(keys []string, u *UserCategory) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "user_id":
			out["user_id"] = u.UserID
		case "category_id":
			out["category_id"] = u.CategoryID
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode user_category cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// decodeUserCategoryCursor decodes a cursor string into its key values,
// each unmarshaled into the key column's Go type.
func decodeUserCategoryCursor(encoded string, keys []string) (map[string]any, error) {
	raw, err := decodeCursor(encoded, keys)
	if err != nil {
		return nil, err
	}
	var row UserCategory
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "user_id":
			err = json.Unmarshal(raw[key], &row.UserID)
			out[key] = row.UserID
		case "category_id":
			err = json.Unmarshal(raw[key], &row.CategoryID)
			out[key] = row.CategoryID
		}
		if err != nil {
			return nil, err
		}
		if cursorValueIsNull(out[key]) {
			return nil, ErrInvalidCursor
		}
	}
	return out, nil
}

