				// statement.
				junctionWhere, junctionWhereArgs := sql.SubqueryWhere(c.dialect, "j", []sql.Condition{
					sql.Where(c.dialect.QuoteIdentifier("user_id")).In(toAnySlice(chunk)...),
				})
