// resolveO2OJoins inspects FieldOptions and returns JOIN descriptors for each O2O relationship.
// Returns nil if no O2O relationships are requested.
func (c *publicUserClient) resolveO2OJoins(d sql.Dialect, fo *PublicUserFieldOptions) []sql.JoinClause {
	if fo == nil {
		return nil
	}
	var joins []sql.JoinClause
	if fo.Profile != nil {
		joins = append(joins, sql.JoinClause{
			Table: sql.Table{Schema: "public", Name: "profiles"},
			Alias: "p2",
			On:    fmt.Sprintf("p2.%s = p.%s", d.QuoteIdentifier("user_id"), d.QuoteIdentifier("id")),
			// The NULL-detection below reads the target's PK off the scanned
			// row, so the join carries it even when FieldOptions did not ask
			// for it — an unselected PK reads as a LEFT JOIN miss.
			Columns: unionColumns(fo.Profile.Columns(), "id"),
		})
		if fo.Profile.User != nil {
			joins = append(joins, sql.JoinClause{
				Table: sql.Table{Schema: "public", Name: "users"},
				Alias: "u",
				On:    fmt.Sprintf("u.%s = p2.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("user_id")),
				// The NULL-detection below reads the target's PK off the scanned
				// row, so the join carries it even when FieldOptions did not ask
				// for it — an unselected PK reads as a LEFT JOIN miss.
				Columns: unionColumns(fo.Profile.User.Columns(), "id"),
			})
			if fo.Profile.User.Profile != nil {
				joins = append(joins, sql.JoinClause{
					Table: sql.Table{Schema: "public", Name: "profiles"},
					Alias: "p3",
					On:    fmt.Sprintf("p3.%s = u.%s", d.QuoteIdentifier("user_id"), d.QuoteIdentifier("id")),
					// The NULL-detection below reads the target's PK off the scanned
					// row, so the join carries it even when FieldOptions did not ask
					// for it — an unselected PK reads as a LEFT JOIN miss.
					Columns: unionColumns(fo.Profile.User.Profile.Columns(), "id"),
				})
				if fo.Profile.User.Profile.User != nil {
					joins = append(joins, sql.JoinClause{
						Table: sql.Table{Schema: "public", Name: "users"},
						Alias: "u2",
						On:    fmt.Sprintf("u2.%s = p3.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("user_id")),
						// The NULL-detection below reads the target's PK off the scanned
						// row, so the join carries it even when FieldOptions did not ask
						// for it — an unselected PK reads as a LEFT JOIN miss.
						Columns: unionColumns(fo.Profile.User.Profile.User.Columns(), "id"),
					})
					if fo.Profile.User.Profile.User.Profile != nil {
						joins = append(joins, sql.JoinClause{
							Table: sql.Table{Schema: "public", Name: "profiles"},
							Alias: "p4",
							On:    fmt.Sprintf("p4.%s = u2.%s", d.QuoteIdentifier("user_id"), d.QuoteIdentifier("id")),
							// The NULL-detection below reads the target's PK off the scanned
							// row, so the join carries it even when FieldOptions did not ask
							// for it — an unselected PK reads as a LEFT JOIN miss.
							Columns: unionColumns(fo.Profile.User.Profile.User.Profile.Columns(), "id"),
						})
						if fo.Profile.User.Profile.User.Profile.User != nil {
							joins = append(joins, sql.JoinClause{
								Table: sql.Table{Schema: "public", Name: "users"},
								Alias: "u3",
								On:    fmt.Sprintf("u3.%s = p4.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("user_id")),
								// The NULL-detection below reads the target's PK off the scanned
								// row, so the join carries it even when FieldOptions did not ask
								// for it — an unselected PK reads as a LEFT JOIN miss.
								Columns: unionColumns(fo.Profile.User.Profile.User.Profile.User.Columns(), "id"),
							})
						}
					}
				}
			}
		}
	}
	return joins
}

// scanPublicUsersWithOneToOneJoins scans rows from a LEFT JOIN query into
// PublicUser entities with O2O relationships populated.
// Routes columns by alias prefix and detects LEFT JOIN misses via NULL PK detection.
func scanPublicUsersWithOneToOneJoins(rows database.Rows, columns []string) ([]*PublicUser, error) {
	var result []*PublicUser
	for rows.Next() {
		p := &PublicUser{}
		p2 := &Profile{}
		p2HasData := false
		p3 := &Profile{}
		p3HasData := false
		p4 := &Profile{}
		p4HasData := false
		u := &PublicUser{}
		uHasData := false
		u2 := &PublicUser{}
		u2HasData := false
		u3 := &PublicUser{}
		u3HasData := false

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "p.id":
				targets[idx] = &p.ID
			case "p.email":
				targets[idx] = &p.Email
			case "p.name":
				targets[idx] = &p.Name
			case "p.role":
				targets[idx] = &p.Role
			case "p.tags":
				targets[idx] = &p.Tags
			case "p.metadata":
				targets[idx] = &p.Metadata
			case "p.created_at":
				targets[idx] = &p.CreatedAt
			case "p.updated_at":
				targets[idx] = &p.UpdatedAt
			case "p2.id":
				targets[idx] = database.NullScan(&p2.ID)
				p2HasData = true
			case "p2.user_id":
				targets[idx] = database.NullScan(&p2.UserID)
			case "p2.bio":
				targets[idx] = &p2.Bio
			case "p2.avatar_url":
				targets[idx] = &p2.AvatarURL
			case "p2.address":
				targets[idx] = &p2.Address
			case "p2.scores":
				targets[idx] = &p2.Scores
			case "p2.created_at":
				targets[idx] = database.NullScan(&p2.CreatedAt)
			case "p3.id":
				targets[idx] = database.NullScan(&p3.ID)
				p3HasData = true
			case "p3.user_id":
				targets[idx] = database.NullScan(&p3.UserID)
			case "p3.bio":
				targets[idx] = &p3.Bio
			case "p3.avatar_url":
				targets[idx] = &p3.AvatarURL
			case "p3.address":
				targets[idx] = &p3.Address
			case "p3.scores":
				targets[idx] = &p3.Scores
			case "p3.created_at":
				targets[idx] = database.NullScan(&p3.CreatedAt)
			case "p4.id":
				targets[idx] = database.NullScan(&p4.ID)
				p4HasData = true
			case "p4.user_id":
				targets[idx] = database.NullScan(&p4.UserID)
			case "p4.bio":
				targets[idx] = &p4.Bio
			case "p4.avatar_url":
				targets[idx] = &p4.AvatarURL
			case "p4.address":
				targets[idx] = &p4.Address
			case "p4.scores":
				targets[idx] = &p4.Scores
			case "p4.created_at":
				targets[idx] = database.NullScan(&p4.CreatedAt)
			case "u.id":
				targets[idx] = database.NullScan(&u.ID)
				uHasData = true
			case "u.email":
				targets[idx] = database.NullScan(&u.Email)
			case "u.name":
				targets[idx] = database.NullScan(&u.Name)
			case "u.role":
				targets[idx] = database.NullScan(&u.Role)
			case "u.tags":
				targets[idx] = &u.Tags
			case "u.metadata":
				targets[idx] = &u.Metadata
			case "u.created_at":
				targets[idx] = database.NullScan(&u.CreatedAt)
			case "u.updated_at":
				targets[idx] = &u.UpdatedAt
			case "u2.id":
				targets[idx] = database.NullScan(&u2.ID)
				u2HasData = true
			case "u2.email":
				targets[idx] = database.NullScan(&u2.Email)
			case "u2.name":
				targets[idx] = database.NullScan(&u2.Name)
			case "u2.role":
				targets[idx] = database.NullScan(&u2.Role)
			case "u2.tags":
				targets[idx] = &u2.Tags
			case "u2.metadata":
				targets[idx] = &u2.Metadata
			case "u2.created_at":
				targets[idx] = database.NullScan(&u2.CreatedAt)
			case "u2.updated_at":
				targets[idx] = &u2.UpdatedAt
			case "u3.id":
				targets[idx] = database.NullScan(&u3.ID)
				u3HasData = true
			case "u3.email":
				targets[idx] = database.NullScan(&u3.Email)
			case "u3.name":
				targets[idx] = database.NullScan(&u3.Name)
			case "u3.role":
				targets[idx] = database.NullScan(&u3.Role)
			case "u3.tags":
				targets[idx] = &u3.Tags
			case "u3.metadata":
				targets[idx] = &u3.Metadata
			case "u3.created_at":
				targets[idx] = database.NullScan(&u3.CreatedAt)
			case "u3.updated_at":
				targets[idx] = &u3.UpdatedAt
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan user with joins: %w", err)
		}

		// NULL detection — assign deepest chain first, then parents
		if u3HasData && u3.ID != (uuid.UUID{}) {
			p4.User = u3
		} else {
			p4.User = nil
		}
		if u2HasData && u2.ID != (uuid.UUID{}) {
			p3.User = u2
		} else {
			p3.User = nil
		}
		if uHasData && u.ID != (uuid.UUID{}) {
			p2.User = u
		} else {
			p2.User = nil
		}
		if p4HasData && p4.ID != (uuid.UUID{}) {
			u2.Profile = p4
		} else {
			u2.Profile = nil
		}
		if p3HasData && p3.ID != (uuid.UUID{}) {
			u.Profile = p3
		} else {
			u.Profile = nil
		}
		if p2HasData && p2.ID != (uuid.UUID{}) {
			p.Profile = p2
		} else {
			p.Profile = nil
		}

		result = append(result, p)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate user rows: %w", err)
	}
	return result, nil
}

// Warehouse - Storage warehouses with type-overridden columns
type Warehouse struct {
	// ID - Unique identifier
	ID uuid.UUID `db:"id" json:"id"`
	// ExternalID - External reference ID (KSUID)
	ExternalID ksuid.KSUID `db:"external_id" json:"external_id"`
	// Name - Warehouse name
	Name string `db:"name" json:"name"`
	// Region - Optional regional designation (custom Optional[string] override)
	Region customtypes.OptionalString `db:"region" json:"region"`
	// Price - Operational cost
	Price decimal.Decimal `db:"price" json:"price"`
	// NullablePrice - Optional secondary price
	NullablePrice decimal.NullDecimal `db:"nullable_price" json:"nullable_price"`
	// RelatedIDS - Related warehouse UUIDs
	RelatedIDS []uuid.UUID `db:"related_ids" json:"related_ids"`
	// NullableRef - Optional reference to another warehouse
	NullableRef *uuid.UUID `db:"nullable_ref" json:"nullable_ref"`
	// AllowedRoles - Permitted user roles for warehouse access
	AllowedRoles UserRoleSlice `db:"allowed_roles" json:"allowed_roles"`
	// TagIDS - Array of KSUID tag references
	TagIDS []ksuid.KSUID `db:"tag_ids" json:"tag_ids"`
	// CreatedAt - Row creation timestamp
	CreatedAt time.Time `db:"created_at" json:"created_at"`

	// Warehouse - one-to-one relationship with the warehouses table.
	Warehouse *Warehouse `db:"-" json:"warehouse"`
	// Warehouses - one-to-many relationship with the warehouses table.
	Warehouses []*Warehouse `db:"-" json:"warehouses"`
}

// WarehouseClient provides type-safe operations for the warehouses table.
type WarehouseClient interface {
	// --- Read Operations ---

	// Get returns a single warehouse by primary key.
	Get(ctx context.Context, id uuid.UUID, opts ...func(*CallOptions[WarehouseFieldOptions])) (*Warehouse, error)

	// GetMany returns warehouses matching the given filter, field selection, and sort criteria.
	// When FieldOptions includes O2M or M2M relationships, they are loaded via an
	// errgroup fan-out — in parallel over the pool, and serialized by the
	// transaction's connection reservation when ctx carries one.
	GetMany(ctx context.Context, input *GetWarehousesInput, opts ...func(*CallOptions[WarehouseFieldOptions])) ([]*Warehouse, error)

	// Exists returns true if a warehouse with the given primary key exists.
	Exists(ctx context.Context, id uuid.UUID, opts ...func(*CallOptions[WarehouseFieldOptions])) (bool, error)

	// ExistsWhere returns true if any warehouse matches the given filter.
	ExistsWhere(ctx context.Context, filter *WarehouseFilter, opts ...func(*CallOptions[WarehouseFieldOptions])) (bool, error)

	// Count returns the number of warehouses matching the given filter.
	Count(ctx context.Context, filter *WarehouseFilter, opts ...func(*CallOptions[WarehouseFieldOptions])) (int64, error)

	// --- Write Operations ---

	// Create inserts a new warehouse and returns the created entity.
	Create(ctx context.Context, input *CreateWarehouseInput, opts ...func(*CallOptions[WarehouseFieldOptions])) (*Warehouse, error)

	// CreateMany inserts multiple warehouses in batches and returns all created entities.
	// Sub-batches are not automatically rolled back on failure — wrap in a transaction for atomicity.
	CreateMany(ctx context.Context, inputs []*CreateWarehouseInput, opts ...func(*CallOptions[WarehouseFieldOptions])) ([]*Warehouse, error)

	// Update partially updates a warehouse by primary key and returns the updated entity.
	// Only fields where IsSet() is true are included in the SET clause.
	// Returns ErrNotFound if the primary key does not exist.
	Update(ctx context.Context, id uuid.UUID, input *UpdateWarehouseInput, opts ...func(*CallOptions[WarehouseFieldOptions])) (*Warehouse, error)

	// UpdateMany updates multiple warehouses and returns the updated entities.
	UpdateMany(ctx context.Context, items []UpdateWarehouseItem, opts ...func(*CallOptions[WarehouseFieldOptions])) ([]*Warehouse, error)

	// UpdateWhere updates all warehouses matching the filter and returns the updated entities.
	// Idempotent — returns empty slice when no rows match.
	UpdateWhere(ctx context.Context, filter *WarehouseFilter, input *UpdateWarehouseInput, opts ...func(*CallOptions[WarehouseFieldOptions])) ([]*Warehouse, error)

	// Upsert inserts a warehouse or updates it on conflict and returns the resulting entity.
	Upsert(ctx context.Context, input *CreateWarehouseInput, target WarehouseConflictTarget, opts ...func(*CallOptions[WarehouseFieldOptions])) (*Warehouse, error)

	// UpsertMany inserts or updates multiple warehouses in batches and returns all resulting entities.
	// Inputs resolving to the same conflict target are deduped, last occurrence wins.
	UpsertMany(ctx context.Context, inputs []*CreateWarehouseInput, target WarehouseConflictTarget, opts ...func(*CallOptions[WarehouseFieldOptions])) ([]*Warehouse, error)

	// Increment atomically increments or decrements a numeric column on a warehouse.
	// Returns ErrNotFound if the primary key does not exist.
	Increment(ctx context.Context, id uuid.UUID, input IncrementInput[WarehouseIncrementColumn], opts ...func(*CallOptions[WarehouseFieldOptions])) error

	// --- Hard Delete Operations ---

	// HardDelete permanently removes a warehouse from the database.
	// Idempotent — returns nil if the primary key does not exist.
	HardDelete(ctx context.Context, id uuid.UUID, opts ...func(*CallOptions[WarehouseFieldOptions])) error

	// HardDeleteMany permanently removes multiple warehouses from the database.
	HardDeleteMany(ctx context.Context, ids []uuid.UUID, opts ...func(*CallOptions[WarehouseFieldOptions])) error

	// HardDeleteWhere permanently removes all warehouses matching the filter.
	// Idempotent — returns nil when no rows match.
	HardDeleteWhere(ctx context.Context, filter *WarehouseFilter, opts ...func(*CallOptions[WarehouseFieldOptions])) error

	// --- Pagination Operations ---

	// Paginate returns a page of warehouses with total count for offset-based pagination.
	Paginate(ctx context.Context, input PaginateInput[WarehouseFilter], opts ...func(*CallOptions[WarehouseFieldOptions])) (*PaginateResult[Warehouse], error)

	// Connection returns a Relay-style cursor-paginated connection of warehouses.
	// Sort order is determined by cursor_keys — custom sorts are not supported.
	// Use Paginate for custom sort orders.
	Connection(ctx context.Context, input ConnectionInput[WarehouseFilter], opts ...func(*CallOptions[WarehouseFieldOptions])) (*Connection[Warehouse], error)

	// Stream returns an iterator over warehouses matching the filter and sort criteria.
	// Rows are yielded as the driver returns them; cache is bypassed.
	// Stream cannot load relationships.
	//
	// Stream refuses an active transaction unless CallOptions.AllowInTransaction
	// is set, and the opt-in commits the caller to issuing nothing else on that
	// txCtx: the one rule that remains the caller's — drain or close a result set
	// before issuing the next statement on that txCtx — applied to a loop whose
	// body is caller code.
	Stream(ctx context.Context, input *StreamWarehousesInput, opts ...func(*CallOptions[StreamWarehouseFieldOptions])) iter.Seq2[*Warehouse, error]
}

